root=Path('/kaggle/working/pair_code');root.mkdir(parents=True,exist_ok=True)
payload=json.loads(zlib.decompress(base64.b64decode('')))
for name,text in payload.items():(root/name).write_text(text)
sys.path.insert(0,str(root))
